(function(){
  var G=Arena.Game; G._running=false;

  /* Caja envolvente en MUNDO de una malla, recorriendo sus vértices. Se usa
     la matriz viva, así que refleja el skinning del fotograma. */
  function caja(obj){
    var g=obj.geometry; if(!g||!g.attributes||!g.attributes.position) return null;
    var pos=g.attributes.position, m=obj.matrixWorld.elements;
    var mn=[1e9,1e9,1e9], mx=[-1e9,-1e9,-1e9], malo=false;
    /* Muestreo: 64 vértices bastan para una caja y esto corre en diez estados
       por seis clases. Recorrer 50.000 por pieza no añade información. */
    var paso=Math.max(1, Math.floor(pos.count/64));
    for(var i=0;i<pos.count;i+=paso){
      var x=pos.getX(i),y=pos.getY(i),z=pos.getZ(i);
      var wx=m[0]*x+m[4]*y+m[8]*z+m[12];
      var wy=m[1]*x+m[5]*y+m[9]*z+m[13];
      var wz=m[2]*x+m[6]*y+m[10]*z+m[14];
      if(!(wx===wx)||!(wy===wy)||!(wz===wz)){ malo=true; continue; }
      if(wx<mn[0])mn[0]=wx; if(wx>mx[0])mx[0]=wx;
      if(wy<mn[1])mn[1]=wy; if(wy>mx[1])mx[1]=wy;
      if(wz<mn[2])mn[2]=wz; if(wz>mx[2])mx[2]=wz;
    }
    if(mn[0]>1e8) return null;
    return {mn:mn,mx:mx,malo:malo};
  }

  /* Foto del equipo: centro de cada pieza en mundo, en orden estable. */
  window.__foto=function(v){
    v.root.updateMatrixWorld(true);
    var out=[];
    (v.gear||[]).forEach(function(o){
      o.traverse(function(c){
        if(!c.isMesh||c.isSkinnedMesh) return;
        var b=caja(c); if(!b) return;
        /* Se anota tambien donde esta el HUESO del que cuelga la pieza. Sin
           ese dato, un brazo en el extremo de su balanceo -que en un andar
           natural queda quieto en el mundo, igual que el pie apoyado- se lee
           como si la pieza estuviera dibujada en espacio de mundo. */
        var hb=c.parent, he=hb?hb.matrixWorld.elements:null;
        /* La transformada LOCAL de la pieza respecto a su hueso. Es EL
           invariante: una pieza colgada de un hueso tiene local constante y el
           skinning la arrastra. Una pieza dibujada por error en espacio de
           mundo tendria local cambiante. Comparar cuanto se MUEVE la pieza
           contra cuanto se mueve el cuerpo -o incluso contra su propio hueso-
           es un mal test: un antebrazo que balancea gira alrededor de un punto,
           y un trozo cerca de ese punto se queda quieto en el mundo estando
           perfectamente pegado. Eso costo dos falsos positivos. */
        out.push({n:(c.name||o.name||'?'),
          c:[(b.mn[0]+b.mx[0])/2,(b.mn[1]+b.mx[1])/2,(b.mn[2]+b.mx[2])/2],
          h:he?[he[12],he[13],he[14]]:null,
          l:[c.position.x,c.position.y,c.position.z,c.quaternion.x,c.quaternion.y,c.quaternion.z,c.quaternion.w],
          malo:b.malo});
      });
    });
    return out;
  };

  /* Posición mundial de cada hueso del rig, en orden estable. */
  window.__huesos=function(v){
    var out=[]; if(!v.rigBones) return out;
    for(var n in v.rigBones){ var e=v.rigBones[n].matrixWorld.elements; out.push([e[12],e[13],e[14]]); }
    return out;
  };

  /* Ejecuta un estado de animación por la ruta REAL del jugador y devuelve
     dos fotos consecutivas del equipo más la posición del cuerpo. */
  window.__estado=function(clase, modo){
    var W=G.world;
    G.setPlayerClass(clase);
    var p=W.getPlayer();          // hay que volver a pedirlo: setPlayerClass lo rehace
    var otros=W.entities.filter(function(e){return e.id!==p.id;});
    for(var k=0;k<otros.length;k++){ otros[k].pos.x=90; otros[k].pos.z=90; }
    p.pos.x=0; p.pos.z=0; p.pos.y=0; p.yaw=0; p.alive=true; p.hp=p.hpMax;
    p.targetId=null;
    var i, v=G.renderer.visuals[p.id];

    /* Asentar: el equipo se cuelga en el primer applyPose, así que hace falta
       al menos un render antes de fotografiar nada. */
    for(i=0;i<14;i++){ W.stepSeconds(1/30); G.renderer.syncVisuals(1/30); }
    G.renderer.render(1,1/30);
    v=G.renderer.visuals[p.id];

    var arche=Arena.Data.archetypeOf(clase);
    var AS=Arena.Combat.AbilitySystem;
    var cls=Arena.Data.classes[clase];

    if(modo==='NORMAL'){ p.autoAttackOn=true; p.combatMode=true;
      var dummy=otros[0]; if(dummy){ dummy.pos.x=0; dummy.pos.z=1.6; p.targetId=dummy.id; } }
    if(modo==='ABILITY'||modo==='CAST'){
      var dummy2=otros[0]; if(dummy2){ dummy2.pos.x=0; dummy2.pos.z=2.4; p.targetId=dummy2.id; }
      if(cls&&cls.abilities&&cls.abilities.length) AS.tryUse(W,p,cls.abilities[0]);
    }
    if(modo==='JUMP') p._jumpRequested=true;
    if(modo==='HIT'&&v&&v.handle&&Arena.Render.CharacterBackend.current.triggerHurt)
      Arena.Render.CharacterBackend.current.triggerHurt(v.handle,p,{x:0,y:0,z:3});
    if(modo==='DEATH'){ p.alive=false; p.hp=0; }

    /* Avanzar hasta el medio del gesto. */
    var n = (modo==='DEATH')?16 : (modo==='JUMP')?7 : (modo==='FORWARD'||modo==='BACKWARD'||modo==='STRAFE')?24 : 6;
    var dz=(modo==='FORWARD')?0.05:(modo==='BACKWARD')?-0.04:0;
    var dx=(modo==='STRAFE')?0.05:0;
    for(i=0;i<n;i++){ p.pos.z+=dz; p.pos.x+=dx; W.stepSeconds(1/30); G.renderer.syncVisuals(1/30); }
    G.renderer.render(1,1/30);
    var A=window.__foto(v), pos1={x:p.pos.x,z:p.pos.z};
    var H1=window.__huesos(v);

    /* Un fotograma más, con el cuerpo desplazándose igual. */
    p.pos.z+=dz; p.pos.x+=dx;
    W.stepSeconds(1/30); G.renderer.syncVisuals(1/30); G.renderer.render(1,1/30);
    var B=window.__foto(v), pos2={x:p.pos.x,z:p.pos.z};
    var H2=window.__huesos(v);
    /* Cuánto se movió el CUERPO en ese fotograma. Sin este dato, el arranque
       de un clip de ataque —que mueve el esqueleto entero de golpe— se lee
       como si cada pieza de equipo se hubiera soltado a la vez. */
    var maxHueso=0;
    for(var h=0;h<H1.length&&h<H2.length;h++){
      var d0=H1[h], d1=H2[h];
      var mv=Math.sqrt(Math.pow(d1[0]-d0[0],2)+Math.pow(d1[1]-d0[1],2)+Math.pow(d1[2]-d0[2],2));
      if(mv>maxHueso) maxHueso=mv;
    }

    return {A:A,B:B,pos1:pos1,pos2:pos2,maxHueso:maxHueso,
            desplaz:Math.abs(pos2.x-pos1.x)+Math.abs(pos2.z-pos1.z)};
  };
  return 'listo';
})()

(function(){
  var clases=['devastador','guardian','centinela','rastreador','arcanista','vinculador'];
  var modos=['IDLE','FORWARD','BACKWARD','STRAFE','NORMAL','ABILITY','JUMP','HIT','DEATH'];
  var fail=[], resumen={};
  for(var c=0;c<clases.length;c++){
    var clase=clases[c];
    var esCaster=Arena.Data.archetypeOf(clase)==='caster';
    var lista=modos.concat(esCaster?['CAST']:[]);
    var piezasBase=null;
    for(var m=0;m<lista.length;m++){
      var modo=lista[m];
      var r=window.__estado(clase,modo);
      var etq=clase+'/'+modo;

      if(!r.A.length){ fail.push(etq+': el equipo desapareció'); continue; }
      if(piezasBase===null) piezasBase=r.A.length;
      else if(r.A.length!==piezasBase)
        fail.push(etq+': el equipo cambia de tamaño ('+r.A.length+' vs '+piezasBase+')');

      var centro={x:r.pos1.x, z:r.pos1.z};
      for(var i=0;i<r.A.length;i++){
        var a=r.A[i];
        if(a.malo){ fail.push(etq+': matriz no finita en '+a.n); continue; }
        /* DESPRENDIMIENTO. Un báculo alto y un espadón llegan a ~1.5 del
           cuerpo; 2.6 sólo se alcanza si la pieza se soltó del hueso. */
        var dx=a.c[0]-centro.x, dy=a.c[1]-1.0, dz=a.c[2]-centro.z;
        var d=Math.sqrt(dx*dx+dy*dy+dz*dz);
        if(d>2.6) fail.push(etq+': '+a.n+' a '+d.toFixed(2)+' del cuerpo');
      }

      /* SEGUIMIENTO Y JITTER, comparando por ÍNDICE: emparejar por nombre
         compara la hombrera izquierda contra la derecha y produce medio metro
         de «salto» que no existe. */
      if(r.B.length===r.A.length){
        for(var j=0;j<r.A.length;j++){
          var p0=r.A[j].c, p1=r.B[j].c;
          var mv=Math.sqrt(Math.pow(p1[0]-p0[0],2)+Math.pow(p1[1]-p0[1],2)+Math.pow(p1[2]-p0[2],2));
          /* Tope generoso: la punta de un báculo que además rota recorre más
             que el cuerpo. Lo que se busca es el POP, no el movimiento. */
          /* El listón es el propio CUERPO. Si el esqueleto se movió 0.6 en ese
             fotograma —arranque de un clip de ataque—, una pieza colgada de él
             moviéndose 0.6 hace exactamente lo que debe. Lo que se busca es que
             la pieza se mueva MÁS que su hueso. */
          if(mv > r.maxHueso*1.35 + 0.10)
            fail.push(etq+': pop de '+mv.toFixed(3)+' con el cuerpo en '+r.maxHueso.toFixed(3)+' — '+r.A[j].n);
          /* Si el cuerpo avanza y la pieza no, está dibujada en espacio de
             mundo por error. Las piezas del PIE quedan fuera: durante el apoyo
             el pie está clavado en el suelo mientras el cuerpo pasa por encima
             —foot locking haciendo su trabajo—, así que una bota que no se
             mueve es lo correcto y no un defecto. */
          /* La pregunta real es «¿la pieza sigue a SU hueso?», no «¿la pieza
             se mueve tanto como el cuerpo?». Un pie apoyado y un brazo en el
             extremo de su balanceo se quedan quietos en el mundo A PROPOSITO,
             y su hueso tambien. Se compara pieza contra su propio hueso. */
          var lA=r.A[j].l, lB=r.B[j].l;
          if(lA&&lB){ var dl=0; for(var q=0;q<7;q++) dl+=Math.abs(lB[q]-lA[q]);
            if(dl>1e-4) fail.push(etq+': '+r.A[j].n+' cambia su transformada local ('+dl.toFixed(5)+'): no esta colgado del hueso, alguien lo dibuja aparte'); }
        }
      }
      resumen[etq]=r.A.length;
    }
  }
  return {assert:!fail.length, fail:fail.slice(0,14),
          estados:Object.keys(resumen).length,
          piezasPorClase:{devastador:resumen['devastador/IDLE'],guardian:resumen['guardian/IDLE'],
            centinela:resumen['centinela/IDLE'],rastreador:resumen['rastreador/IDLE'],
            arcanista:resumen['arcanista/IDLE'],vinculador:resumen['vinculador/IDLE']}};
})()
